import json

# Solution based on demo: fill enclosed 0s with 8, keep 2s intact
# Enclosed means: 0s inside a rectangular box made of 2s

def transform(grid):
    if not grid or not grid[0]:
        return grid

    N, M = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    # Find all rectangular boxes of 2s and fill interior 0s with 8
    for r1 in range(N):
        for c1 in range(M):
            if grid[r1][c1] == 2:
                # Try to find a box with top-left at (r1, c1)
                # Find farthest cell with 2 in same row to the right
                c2 = M - 1
                while c2 > c1 and grid[r1][c2] == 0:
                    c2 -= 1

                # Check if right cell is 2
                if c1 < c2 and grid[r1][c2] == 2:
                    # Find bottom edge in column c1 or c2
                    r2 = N - 1
                    while r2 > r1 and grid[r2][c1] == 0:
                        r2 -= 1
                    if r1 < r2:
                        if grid[r2][c1] == 2 and grid[r2][c2] == 2:
                            # Now check if top and bottom are connected (or close)
                            # Check left and right lines
                            right_ok = all(grid[r][c2] == 2 for r in range(r1, r2+1))
                            if (all(grid[r1][c] == 2 for c in range(c1, c2+1)) and right_ok):
                                # Box found at (r1,c1) to (r2,c2)
                                for r in range(r1 + 1, r2):
                                    for c in range(c1 + 1, c2):
                                        if output[r][c] == 0:
                                            output[r][c] = 8

    return output

