def transform_fixed(grid):
    if not grid or not grid[0]:
        return grid

    N, M = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    # Find all rectangular boxes of 2s and fill their interior
    # A box is defined by:
    # - Top edge: row r1, cols c1 to c2: all 2s
    # - Bottom edge: row r2, cols c1 to c2: all 2s
    # - Left edge: col c1, rows r1+1 to r2-1: all 2s
    # - Right edge: col c2, rows r1+1 to r2-1: all 2s

    def is_box(r1, c1, r2, c2):
        if r1 >= r2 or c1 >= c2:
            return False
        # Check top and bottom
        for c in range(c1, c2 + 1):
            if grid[r1][c] != 2 or grid[r2][c] != 2:
                return False
        # Check left and right
        for r in range(r1 + 1, r2):
            if grid[r][c1] != 2 or grid[r][c2] != 2:
                return False
        return True

    for r1 in range(N):
        for c1 in range(M):
            if grid[r1][c1] == 2:
                for r2 in range(r1 + 1, N):
                    for c2 in range(c1 + 1, M):
                        if is_box(r1, c1, r2, c2):
                            # Fill interior with 8, but skip non-0 cells (they stay as is)
                            for r in range(r1 + 1, r2):
