            for r2 in range(r1 + 2, height):
                for c2 in range(c1 + 2, width):
                    # Check top edge
                    top_ok = all(grid[r1][c] == 2 for c in range(c1, c2 + 1))
                    # Check bottom edge  
                    bottom_ok = all(grid[r2][c] == 2 for c in range(c1, c2 + 1))
                    # Check left edge
                    left_ok = all(grid[r][c1] == 2 for r in range(r1 + 1, r2))
                    # Check right edge
                    right_ok = all(grid[r][c2] == 2 for r in range(r1 + 1, r2))

                    if top_ok and bottom_ok and left_ok and right_ok:
                        # Find interior 2s
