test_input = [[int(x) for x in line.split()] for line in test_input_str.strip().split('\n')]
boxes = [(0,11,4,15), (1,1,9,9), (7,13,11,17), (12,5,18,11)]

# Debug: Check each cell of each box's boundary includes 2s
all_boundary_2s = True
for r1, c1, r2, c2 in boxes:
    errors = []
    # Top row
    for c in range(c1, c2+1):
        if test_input[r1][c] != 2:
            errors.append(f"Top ({r1},{c})={test_input[r1][c]}")
    # Bottom row
    for c in range(c1, c2+1):
        if test_input[r2][c] != 2:
            errors.append(f"Bottom ({r2},{c})={test_input[r2][c]}")
    # Left column
    for r in range(r1+1, r2):
        if test_input[r][c1] != 2:
            errors.append(f"Left ({r},{c1})={test_input[r][c1]}")
    # Right column
    for r in range(r1+1, r2):
        if test_input[r][c2] != 2:
            errors.append(f"Right ({r},{c2})={test_input[r][c2]}")

    if errors:
        print(f"Box ({r1},{c1})-({r2},{c2}) boundary errors:")
        for e in errors[:5]:
            print(f"  {e}")
        if len(errors) > 5:
            print(f"  ... and {len(errors)-5} more")
        all_boundary_2s = False
    else:
        print(f"Box ({r1},{c1})-({r2},{c2}): boundary OK (all 2s)")

print(f"\nAll boundaries valid: {all_boundary_2s}")

